38	// 1. EL SISTEMA DE PARTÍCULAS DE FONDO
39	const BG_PARTICLES = 20000; // Incrementado para mayor densidad
40	
41	function BackgroundParticles() {
42	  const materialRef = useRef<THREE.ShaderMaterial>(null);
43	  
44	  const { positions, isRight } = useMemo(() => {
45	    const pos = new Float32Array(BG_PARTICLES * 3);
46	    const isR = new Float32Array(BG_PARTICLES);
47	    
48	    const spacing = 0.7;
49	
50	    for(let i=0; i<BG_PARTICLES; i++) {
51	       if (i % 2 === 0) {
52	          // Izquierda: Matriz estructurada (Grid)
53	          let x = -1 - Math.random() * 20; 
54	          x = Math.round(x / spacing) * spacing;
55	          let y = (Math.random() * 24 - 12);
56	          y = Math.round(y / spacing) * spacing;
57	          let z = (Math.random() * 12 - 6);
58	          z = Math.round(z / spacing) * spacing;
59	          
60	          pos[i*3] = x;
61	          pos[i*3+1] = y;
62	          pos[i*3+2] = z;
63	          isR[i] = 0.0;
64	       } else {
65	          // Derecha: Nube de Caos Orgánico
66	          pos[i*3] = 1 + Math.random() * 20;
67	          pos[i*3+1] = Math.random() * 24 - 12;
68	          pos[i*3+2] = Math.random() * 12 - 6;
69	          isR[i] = 1.0;
70	       }
71	    }
72	    return { positions: pos, isRight: isR };
73	  }, []);
74	
75	  useFrame((state) => {
76	    if (materialRef.current) {
77	      materialRef.current.uniforms.uTime.value = state.clock.elapsedTime;
78	    }
79	  });
80	
81	  const vertexShader = `
82	    attribute float isRight;
83	    uniform float uTime;
84	    varying vec3 vColor;
85	    varying float vAlpha;
86	    
87	    void main() {
88	      vec3 pos = position;
89	      
90	      if (isRight < 0.5) {
91	        // Lógica: Datos fluyendo, estructura viva
92	        float wave = sin(pos.x * 2.0 + uTime * 3.0) * cos(pos.z * 2.0 + uTime * 2.0);
93	        pos.y += wave * 0.15;
94	        vColor = mix(vec3(0.0, 0.8, 1.0), vec3(0.0, 1.0, 0.8), wave);
95	        vAlpha = 0.6; // Visibilidad aumentada
96	      } else {
97	        // Creatividad: Tormenta caótica más dinámica
98	        float noise = sin(pos.y * 2.0 + uTime * 2.0) * cos(pos.z * 2.0 + uTime * 1.5);
99	        pos.x += noise * 0.5;
100	        pos.y += cos(pos.x * 2.0 + uTime * 2.0) * 0.5;
101	        pos.z += sin(pos.x * 1.0 + uTime) * 0.4;
102	        vColor = mix(vec3(1.0, 0.2, 0.0), vec3(1.0, 0.6, 0.0), noise); 
103	        vAlpha = 0.7; // Visibilidad aumentada
104	      }
105	      
106	      vec4 mvPosition = modelViewMatrix * vec4(pos, 1.0);
107	      
108	      // Efecto de tintineo (twinkling)
109	      float twinkle = 1.0 + sin(uTime * 5.0 + pos.x * 10.0) * 0.3;
110	      gl_PointSize = (10.0 / -mvPosition.z) * twinkle; 
111	      
112	      gl_Position = projectionMatrix * mvPosition;
113	    }
114	  `;
115	
116	  const fragmentShader = `
117	    varying vec3 vColor;
118	    varying float vAlpha;
119	    void main() {
120	      float dist = length(gl_PointCoord - vec2(0.5));
121	      if (dist > 0.5) discard;
122	      float intensity = 1.0 - (dist * 2.0);
123	      gl_FragColor = vec4(vColor, intensity * vAlpha);
124	    }
125	  `;
126	
127	  return (
128	    <points>
129	      <bufferGeometry>
130	        <bufferAttribute attach="attributes-position" count={BG_PARTICLES} array={positions} itemSize={3} />
131	        <bufferAttribute attach="attributes-isRight" count={BG_PARTICLES} array={isRight} itemSize={1} />
132	      </bufferGeometry>
133	      <shaderMaterial
134	        ref={materialRef}
135	        transparent
136	        depthWrite={false}
137	        blending={THREE.AdditiveBlending}
138	        uniforms={{ uTime: { value: 0 } }}
139	        vertexShader={vertexShader}
140	        fragmentShader={fragmentShader}
141	      />
142	    </points>
143	  );
144	}
