147	// 2. EL SISTEMA FOREGROUND (Líneas desplegables y Nodos)
148	function ForegroundNetwork({ scrollRef, mouseXRef, instructionRef }: { scrollRef: any, mouseXRef: any, instructionRef: any }) {
149	  const lineMats = useRef<any[]>([]);
150	  const nodeMats = useRef<any[]>([]);
151	  const htmlRefs = useRef<(HTMLDivElement | null)[]>([]);
152	  const groupRef = useRef<THREE.Group>(null);
153	  
154	  const smoothProgress = useRef(0);
155	  const smoothMouseX = useRef(0.5);
156	
157	  useFrame((state) => {
158	    smoothProgress.current += (scrollRef.current - smoothProgress.current) * 0.08;
159	    smoothMouseX.current += (mouseXRef.current - smoothMouseX.current) * 0.05;
160	    
161	    // Multiplicamos por 1.5 para que la animación se complete al 66% del scroll
162	    const p = Math.min(1, smoothProgress.current * 1.5);
163	
164	    // Desplegar líneas
165	    const dashOffset = 25 - (p * 25);
166	    lineMats.current.forEach(mat => {
167	      if (mat) mat.dashOffset = dashOffset;
168	    });
169	
170	    // Revelar nodos
171	    const elementOpacity = Math.max(0, Math.min(1, (p - 0.2) * 2.0));
172	    nodeMats.current.forEach(mat => {
173	      if (mat) mat.opacity = elementOpacity;
174	    });
175	    htmlRefs.current.forEach(el => {
176	      if (el) {
177	        el.style.opacity = elementOpacity.toString();
178	        el.style.transform = `scale(${0.8 + elementOpacity * 0.2})`;
179	      }
180	    });
181	
182	    if (instructionRef.current) {
183	       instructionRef.current.style.opacity = Math.max(0, 1.0 - p * 5).toString();
184	    }
185	
186	    if (groupRef.current) {
187	      groupRef.current.rotation.y = (smoothMouseX.current - 0.5) * 0.2;
188	      groupRef.current.position.y = Math.sin(state.clock.elapsedTime * 0.5) * 0.1;
189	    }
190	  });
191	
192	  return (
193	    <group ref={groupRef}>
194	      {/* NÚCLEO CENTRAL MEJORADO */}
195	      <mesh position={[0,0,0]}>
196	        <sphereGeometry args={[0.35, 32, 32]} />
197	        <meshBasicMaterial color="#ffffff" />
198	      </mesh>
199	      {/* Halo Exterior del Núcleo */}
200	      <mesh position={[0,0,0]}>
201	        <sphereGeometry args={[0.45, 16, 16]} />
202	        <meshBasicMaterial color="#ffffff" transparent opacity={0.2} wireframe />
203	      </mesh>
204	      
205	      <Html position={[0, -0.8, 0]} center className="pointer-events-none">
206	        <div className="flex flex-col items-center">
207	          <div className="text-white text-sm md:text-lg font-serif italic tracking-widest uppercase drop-shadow-[0_0_15px_rgba(255,255,255,1)] whitespace-nowrap">
208	            Núcleo de Procesamiento
209	          </div>
210	          <div className="text-white/60 text-[8px] md:text-[10px] font-mono tracking-[0.2em] uppercase mt-2 text-center w-48 border-t border-white/20 pt-2 whitespace-nowrap">
211	            Convergencia Analítico-Creativa
212	          </div>
213	        </div>
214	      </Html>
215	
216	      {/* RAMIFICACIONES */}
217	      {CLUSTERS.map((cluster, i) => {
218	        const isLogical = cluster.type === 0;
219	        return (
220	          <group key={cluster.id}>
221	            
222	            {/* LÍNEAS */}
223	            {isLogical ? (
224	              <Line 
225	                ref={(el: any) => { if (el && el.material) lineMats.current.push(el.material) }}
226	                points={[[0,0,0], [cluster.pos[0], 0, 0], cluster.pos] as any}
227	                color={cluster.color}
228	                lineWidth={1.5}
229	                transparent
230	                opacity={0.8}
231	                dashed
232	                dashSize={25}
233	                gapSize={25}
234	              />
235	            ) : (
236	              <QuadraticBezierLine 
237	                ref={(el: any) => { if (el && el.material) lineMats.current.push(el.material) }}
238	                start={[0,0,0]}
239	                end={cluster.pos as any}
240	                mid={[cluster.pos[0] * 0.5, cluster.pos[1] * 0.5 + 4, cluster.pos[2] * 0.5] as any}
241	                color={cluster.color}
242	                lineWidth={1.5}
243	                transparent
244	                opacity={0.8}
245	                dashed
246	                dashSize={25}
247	                gapSize={25}
248	              />
249	            )}
250	
251	            {/* NODOS */}
252	            <mesh position={cluster.pos as any}>
253	              {isLogical ? <boxGeometry args={[0.2, 0.2, 0.2]} /> : <sphereGeometry args={[0.15, 16, 16]} />}
254	              <meshBasicMaterial 
255	                ref={(el) => { if(el) nodeMats.current.push(el) }}
256	                color={cluster.color} 
257	                transparent 
258	                opacity={0} 
259	              />
260	            </mesh>
261	
262	            {/* ETIQUETAS */}
263	            <Html position={cluster.pos as any} center className="pointer-events-none z-10">
264	              <div 
265	                ref={(el) => { if(el) htmlRefs.current[i] = el; }}
266	                style={{ opacity: 0 }}
267	                className={`whitespace-nowrap backdrop-blur-md px-3 py-1.5 mt-8 border 
268	                  ${isLogical 
269	                    ? 'text-brand-cyan font-mono text-[10px] md:text-xs uppercase tracking-widest bg-[#00ffff]/10 border-brand-cyan/30' 
270	                    : 'text-brand-orange font-serif text-[12px] md:text-sm italic tracking-wide bg-[#ff5a00]/10 border-brand-orange/40 rounded-r-full border-l-2 border-y-0 border-r-0'
271	                  }`}
272	              >
273	                {isLogical ? `[ ${cluster.label} ]` : cluster.label}
274	              </div>
275	            </Html>
276	
277	          </group>
278	        )
279	      })}
280	    </group>
281	  );
282	}
