9	export default function AboutMonet() {
10	  const meshRef = useRef<THREE.Mesh>(null);
11	  const groupRef = useRef<THREE.Group>(null);
12	
13	  useFrame((state) => {
14	    const rawProgress = useStore.getState().scrollProgress;
15	    
16	    if (groupRef.current) {
17	      // Parallax inercial masivo: 
