18	  
19	  useEffect(() => {
20	    let roleIndex = 0;
21	    let intervalId: NodeJS.Timeout;
22	    
23	    const scramble = () => {
24	      const nextRole = ROLES[(roleIndex + 1) % ROLES.length];
