15	    const middleX = clientX - (left + width / 2);
16	    const middleY = clientY - (top + height / 2);
17	    
18	    // Psicología inversa en UI: El botón siente la gravedad del cursor
19	    setPosition({ x: middleX * 0.2, y: middleY * 0.2 });
