26	  return (
27	    <motion.div
28	      ref={ref}
29	      onMouseMove={handleMouse}
30	      onMouseLeave={reset}
31	      animate={{ x: position.x, y: position.y }}
32	      transition={{ type: "spring", stiffness: 150, damping: 15, mass: 0.1 }}
33	      className={`relative inline-block cursor-pointer ${className}`}
