4	import { useFrame } from '@react-three/fiber';
5	import * as THREE from 'three';
6	import { useStore } from '@/store/useStore';
7	
8	const COUNT = 15000; // 15,000 partículas para mantener 60fps constantes
9	
10	const vertexShader = `
11	uniform float uProgress;
12	uniform float uTime;
13	attribute vec3 aTargetPosition;
14	varying float vProgress;
15	
16	void main() {
17	  vec3 pos = position;
18	  
19	  // Caos: Añadir un poco de ruido físico basado en el tiempo
20	  pos.x += sin(uTime * 0.5 + position.y * 5.0) * 0.1 * (1.0 - uProgress);
21	  pos.y += cos(uTime * 0.3 + position.x * 5.0) * 0.1 * (1.0 - uProgress);
22	  pos.z += sin(uTime * 0.4 + position.z * 5.0) * 0.1 * (1.0 - uProgress);
23	
24	  // El núcleo de la narrativa: Mezclar matemáticamente de Caos a Estructura (Orden)
25	  vec3 finalPos = mix(pos, aTargetPosition, uProgress);
26	  
27	  vec4 mvPosition = modelViewMatrix * vec4(finalPos, 1.0);
28	  
29	  // Tamaño adaptativo según la profundidad y el progreso
30	  gl_PointSize = (15.0 / -mvPosition.z) * (1.0 + uProgress * 1.5); 
31	  gl_Position = projectionMatrix * mvPosition;
32	  
33	  vProgress = uProgress;
34	}
35	`;
36	
37	const fragmentShader = `
38	varying float vProgress;
39	uniform float uOpacity;
40	
41	void main() {
42	  // Paleta narrativa: De Blanco/Gris Caótico a Cian Metálico (El Orden)
43	  vec3 colorChaos = vec3(0.4, 0.4, 0.4);
44	  vec3 colorOrder = vec3(0.0, 0.94, 1.0); // #00F0FF (Cian)
45	  
46	  vec3 finalColor = mix(colorChaos, colorOrder, vProgress);
47	  
48	  // Shader para hacer la partícula esférica y luminosa (Gaussian blur-like)
49	  float distanceToCenter = distance(gl_PointCoord, vec2(0.5));
50	  float alpha = 0.05 / distanceToCenter - 0.1;
51	  
52	  gl_FragColor = vec4(finalColor, alpha * uOpacity);
53	}
54	`;
55	
56	export default function HeroParticles() {
57	  const shaderRef = useRef<THREE.ShaderMaterial>(null);
58	  const groupRef = useRef<THREE.Group>(null);
59	  
60	  const [positions, targetPositions] = useMemo(() => {
61	    const pos = new Float32Array(COUNT * 3);
62	    const target = new Float32Array(COUNT * 3);
63	    
64	    const gridSize = Math.floor(Math.cbrt(COUNT));
65	    const spacing = 0.15;
66	    const offset = (gridSize * spacing) / 2;
67	    
68	    for(let i = 0; i < COUNT; i++) {
69	      // Posición Inicial: Esfera aleatoria esparcida (Caos)
70	      const theta = Math.random() * Math.PI * 2;
71	      const phi = Math.acos((Math.random() * 2) - 1);
72	      const r = 2 + Math.random() * 4;
73	      
74	      pos[i * 3 + 0] = r * Math.sin(phi) * Math.cos(theta);
75	      pos[i * 3 + 1] = r * Math.sin(phi) * Math.sin(theta);
76	      pos[i * 3 + 2] = r * Math.cos(phi);
77	      
78	      // Posición Objetivo: Cubo Perfecto Estructurado (Orden)
79	      const x = (i % gridSize);
80	      const y = (Math.floor(i / gridSize) % gridSize);
81	      const z = (Math.floor(i / (gridSize * gridSize)));
82	      
83	      target[i * 3 + 0] = x * spacing - offset;
84	      target[i * 3 + 1] = y * spacing - offset;
85	      target[i * 3 + 2] = z * spacing - offset;
86	    }
87	    
88	    return [pos, target];
89	  }, []);
90	
91	  useFrame((state) => {
92	    if (shaderRef.current && groupRef.current) {
93	      shaderRef.current.uniforms.uTime.value = state.clock.elapsedTime;
94	      
95	      // Obtener el progreso de scroll sin bloquear el main thread de React
96	      const rawProgress = useStore.getState().scrollProgress;
97	      
98	      // Amplificamos la ventana de progreso (0 -> 0.25 en scroll equivale a 0 -> 1 en shader)
99	      const localProgress = Math.min(rawProgress * 4.0, 1.0); 
100	      
101	      // Lerp para suavizado inercial en la GPU
102	      shaderRef.current.uniforms.uProgress.value += (localProgress - shaderRef.current.uniforms.uProgress.value) * 0.05;
103	      
104	      // Rotar la galaxia lentamente
105	      groupRef.current.rotation.y = state.clock.elapsedTime * 0.05;
106	      groupRef.current.rotation.x = state.clock.elapsedTime * 0.02;
107	
108	      // Desvanecer partículas al salir de la sección Hero (progreso > 0.3)
109	      const targetOpacity = rawProgress < 0.3 ? 1.0 - (rawProgress / 0.3) : 0.0;
110	      shaderRef.current.uniforms.uOpacity.value += (targetOpacity - shaderRef.current.uniforms.uOpacity.value) * 0.1;
111	    }
112	  });
113	
114	  return (
115	    <group ref={groupRef}>
116	      <points>
117	        <bufferGeometry>
118	          <bufferAttribute 
119	            attach="attributes-position"
120	            args={[positions, 3]}
121	          />
122	          <bufferAttribute 
123	            attach="attributes-aTargetPosition"
124	            args={[targetPositions, 3]}
125	          />
126	        </bufferGeometry>
127	        <shaderMaterial 
128	          ref={shaderRef}
129	          vertexShader={vertexShader}
130	          fragmentShader={fragmentShader}
131	          uniforms={{
132	            uTime: { value: 0 },
133	            uProgress: { value: 0 },
134	            uOpacity: { value: 1 }
135	          }}
136	          transparent={true}
137	          depthWrite={false}
138	          blending={THREE.AdditiveBlending}
139	        />
140	      </points>
141	    </group>
142	  );
143	}
