30	uniform vec3 uColor;
31	uniform float uActive;
32	
33	void main() {
34	  vec3 color = mix(vec3(0.0), uColor, (vElevation + 1.0) * 0.5 * uActive);
35	  
36	  // Efecto holográfico
37	  float grid = max(step(0.98, fract(vUv.x * 30.0)), step(0.98, fract(vUv.y * 30.0)));
38	  vec3 finalColor = mix(color, uColor * 2.0, grid);
39	  
40	  gl_FragColor = vec4(finalColor, uActive * 0.5);
41	}
42	`;
