44	export default function ProjectsFluid() {
45	  const meshRef = useRef<THREE.Mesh>(null);
46	  const shaderRef = useRef<THREE.ShaderMaterial>(null);
47	
48	  const colors = [
49	    new THREE.Color("#FF5A00"), // 1: Naranja
50	    new THREE.Color("#00F0FF"), // 2: Cian
51	    new THREE.Color("#FF0055"), // 3: Magenta
52	  ];
53	
54	  useFrame((state) => {
55	    const activeProject = useStore.getState().activeProject;
56	    // Mostrar si hay un proyecto activo o si estamos en la zona de scroll de proyectos
57	    const rawProgress = useStore.getState().scrollProgress;
58	    const isSectionActive = rawProgress > 0.7 && rawProgress < 0.95;
59	    
60	    // Si pasamos el ratón por encima, max intensidad. Si solo estamos en la sección, intensidad leve.
61	    const targetActive = activeProject !== null ? 1.0 : (isSectionActive ? 0.3 : 0.0);
62	    
63	    if (shaderRef.current && meshRef.current) {
64	      shaderRef.current.uniforms.uTime.value = state.clock.elapsedTime;
65	      
66	      // Transición suave de estado
67	      shaderRef.current.uniforms.uActive.value += (targetActive - shaderRef.current.uniforms.uActive.value) * 0.1;
68	      
69	      // Cambiar color basado en el proyecto activo
70	      if (activeProject !== null) {
71	        shaderRef.current.uniforms.uColor.value.lerp(colors[activeProject - 1], 0.1);
